mapper.select:
select count(0) from sys_user
delete = false
and user_name like '%'||#{item.userName}||'%'
and itcode like '%'||#{item.itcode}||'%'
and type = #{item.type}
and phone_number = #{item.phoneNumber}

select *
from sys_user
where user_name = #{userName}

select * from sys_user where user_name = #{userName} and delete = #{delete}

    and id != #{userId}

limit 1

select count(1)
from ad_overview
where itcode = #{itcode}

SELECT distinct atun.user_name as id,atun.user_name,atun .email as mail , '-' as description, 'ADFS' as type, CASE WHEN atun.user_name = 'None' THEN 0 ELSE 1 END AS sort_order FROM ad_tb_upp_nature_2 atun where 1=1
and atun.user_name like '%'||#{name}||'%'
ORDER BY sort_order, user_name offset (#{page}-1)*#{size} limit #{size}

SELECT distinct atun.user_name as id,atun.user_name,atun .email as mail ,'-' as description,'ADFS' as
type FROM
ad_tb_upp_nature_2 atun where 1=1

    and atun.user_name like '%'||#{name}||'%'

and atun.user_name in (select user_id from sys_user_roles sur left join sys_role sr on sur.role_id = sr.id where
1= 1

    and sr.name = #{roleName}

and sr.workspace_id = #{workspaceId}
)
